"""Compile-time configurations for native RMSNorm kernels."""

import json
import math
from functools import lru_cache
from pathlib import Path
from typing import NamedTuple

from kestrel_kernels.arch import (
    get_cuda_compute_capability,
    get_cuda_device_name,
    parse_torch_arch_list_entry,
)
from kestrel_kernels.rmsnorm.calibration import validate_artifact


class RmsNormConfig(NamedTuple):
    num_threads: int
    threads_per_row: int


class RmsNormTarget(NamedTuple):
    arch: str
    gpu_name: str
    compute_capability: str
    filename_gpu_key: str


RMSNORM_TARGETS = (
    RmsNormTarget(
        arch="sm90",
        gpu_name="NVIDIA H100 80GB HBM3",
        compute_capability="9.0",
        filename_gpu_key="nvidia_h100_80gb_hbm3",
    ),
    RmsNormTarget(
        arch="sm100",
        gpu_name="NVIDIA B200",
        compute_capability="10.0",
        filename_gpu_key="nvidia_b200",
    ),
)
_TARGET_BY_ARCH = {target.arch: target for target in RMSNORM_TARGETS}
_TARGET_BY_DEVICE = {
    (target.gpu_name, target.compute_capability): target
    for target in RMSNORM_TARGETS
}


def rmsnorm_dynamic_smem_bytes(
    num_threads: int,
    threads_per_row: int,
) -> int:
    """Return shared storage required by the cross-warp reduction."""
    if threads_per_row <= 32:
        return 0
    if threads_per_row != num_threads or num_threads % 32:
        raise ValueError(
            "block-reduce RMSNorm requires one complete CTA per row"
        )

    alignment = 16
    partials_bytes = (num_threads // 32) * 4
    aligned_partials_bytes = (
        (partials_bytes + alignment - 1) // alignment
    ) * alignment
    return aligned_partials_bytes + alignment


# These legacy dimensions predate generated calibration and remain explicitly
# non-authoritative until migrated. Their geometry is target-independent only
# because that is the historical runtime contract. New widths must be resolved
# through a target-qualified generated artifact below.
RMSNORM_CONFIGS = {
    64: RmsNormConfig(128, 8),
    128: RmsNormConfig(128, 16),
    256: RmsNormConfig(128, 32),
    512: RmsNormConfig(128, 32),
    768: RmsNormConfig(128, 32),
    1024: RmsNormConfig(256, 256),
    1152: RmsNormConfig(128, 32),
    1536: RmsNormConfig(128, 128),
    2048: RmsNormConfig(256, 256),
    2304: RmsNormConfig(64, 64),
    2560: RmsNormConfig(128, 128),
    4096: RmsNormConfig(256, 256),
    5120: RmsNormConfig(256, 256),
    5376: RmsNormConfig(64, 64),
}
# Functional four-element-vector warp reduction on unmeasured architectures.
# The column tile must divide the vector count: these kernels have no N mask.
# This does not replace the generated authority on H100/B200.
PORTABLE_RMSNORM_ARCHES = ("sm80", "sm86", "sm87", "sm89", "sm110", "sm120")
GENERATED_RMSNORM_HIDDEN_SIZES = frozenset({72, 2816})
RMSNORM_HIDDEN_SIZES = frozenset(RMSNORM_CONFIGS) | GENERATED_RMSNORM_HIDDEN_SIZES


def rmsnorm_target_for_arch(arch: str) -> RmsNormTarget:
    normalized = parse_torch_arch_list_entry(str(arch))
    try:
        return _TARGET_BY_ARCH[normalized]
    except KeyError as exc:
        raise ValueError(
            f"no generated RMSNorm calibration target for architecture {arch!r}"
        ) from exc


def rmsnorm_target_for_device(device_index: int) -> RmsNormTarget | None:
    gpu_name = get_cuda_device_name(device_index)
    major, minor = get_cuda_compute_capability(device_index)
    compute_capability = f"{major}.{minor}"
    return _TARGET_BY_DEVICE.get((gpu_name, compute_capability))


@lru_cache(maxsize=None)
def _load_generated_config(
    hidden_size: int,
    target: RmsNormTarget,
) -> RmsNormConfig:
    filename = (
        f"rmsnorm_H{hidden_size}_bf16_{target.filename_gpu_key}.json"
    )
    path = Path(__file__).parents[1] / "configs" / filename
    with path.open() as handle:
        artifact = json.load(handle)
    if artifact.get("hidden_size") != hidden_size:
        raise ValueError(
            f"generated RMSNorm artifact {filename!r} has the wrong hidden size"
        )
    config = validate_artifact(
        artifact,
        expected_gpu_name=target.gpu_name,
        expected_compute_capability=target.compute_capability,
    )
    return RmsNormConfig(**config)


def rmsnorm_config_for_arch(hidden_size: int, arch: str) -> RmsNormConfig:
    if hidden_size in RMSNORM_CONFIGS:
        return RMSNORM_CONFIGS[hidden_size]
    if hidden_size not in GENERATED_RMSNORM_HIDDEN_SIZES:
        raise ValueError(f"unsupported RMSNorm hidden size {hidden_size}")
    normalized = parse_torch_arch_list_entry(str(arch))
    if normalized in PORTABLE_RMSNORM_ARCHES:
        return RmsNormConfig(128, math.gcd(hidden_size // 4, 32))
    return _load_generated_config(hidden_size, rmsnorm_target_for_arch(normalized))


def rmsnorm_config_for_device(
    hidden_size: int,
    device_index: int,
) -> tuple[RmsNormConfig, str | None] | None:
    """Resolve runtime geometry and its target-qualified variant architecture."""
    if hidden_size in RMSNORM_CONFIGS:
        return RMSNORM_CONFIGS[hidden_size], None
    if hidden_size not in GENERATED_RMSNORM_HIDDEN_SIZES:
        raise ValueError(f"unsupported RMSNorm hidden size {hidden_size}")
    target = rmsnorm_target_for_device(device_index)
    if target is None:
        major, minor = get_cuda_compute_capability(device_index)
        arch = f"sm{major}{minor}"
        if arch in PORTABLE_RMSNORM_ARCHES:
            return RmsNormConfig(128, math.gcd(hidden_size // 4, 32)), arch
        return None
    return _load_generated_config(hidden_size, target), target.arch


def rmsnorm_variant_key(
    *,
    op: str,
    weight_key: str,
    hidden_size: int,
    target_arch: str | None = None,
    rank4: bool = False,
) -> str:
    if op not in ("rmsnorm", "add_rmsnorm"):
        raise ValueError(f"unsupported RMSNorm operation {op!r}")
    if weight_key not in ("wbf16", "wfp32"):
        raise ValueError(f"unsupported RMSNorm weight type {weight_key!r}")
    if hidden_size not in RMSNORM_HIDDEN_SIZES:
        raise ValueError(f"unsupported RMSNorm hidden size {hidden_size}")
    if hidden_size in GENERATED_RMSNORM_HIDDEN_SIZES:
        normalized = parse_torch_arch_list_entry(target_arch or "")
        target_arch = (normalized if normalized in PORTABLE_RMSNORM_ARCHES
                       else rmsnorm_target_for_arch(normalized).arch)
    elif target_arch is not None:
        raise ValueError(
            "legacy RMSNorm geometry must not use a target-qualified variant"
        )
    if rank4 and (
        op != "rmsnorm" or hidden_size not in STRIDED4D_RMSNORM_HIDDEN_SIZES
    ):
        raise ValueError("unsupported rank-4 RMSNorm variant")
    target = f"_{target_arch}" if target_arch is not None else ""
    layout = "_rank4" if rank4 else ""
    return (
        f"{op}_bf16_{weight_key}_d{hidden_size}{target}{layout}_eps1e-6"
    )


# Fused add + RMSNorm has only been calibrated for these dimensions. Plain
# RMSNorm supports every entry in RMSNORM_HIDDEN_SIZES on a declared target.
ADD_RMSNORM_HIDDEN_SIZES = frozenset({128, 256, 1024, 2048, 2560, 4096, 5120})
STRIDED4D_RMSNORM_HIDDEN_SIZES = frozenset({64, 72, 256, 512})


__all__ = [
    "ADD_RMSNORM_HIDDEN_SIZES",
    "GENERATED_RMSNORM_HIDDEN_SIZES",
    "RMSNORM_CONFIGS",
    "RMSNORM_HIDDEN_SIZES",
    "RMSNORM_TARGETS",
    "RmsNormConfig",
    "RmsNormTarget",
    "STRIDED4D_RMSNORM_HIDDEN_SIZES",
    "rmsnorm_config_for_arch",
    "rmsnorm_config_for_device",
    "rmsnorm_dynamic_smem_bytes",
    "rmsnorm_target_for_arch",
    "rmsnorm_target_for_device",
    "rmsnorm_variant_key",
]
